<?php
namespace ExcelHerbal\ERP7\Security;
use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Domain\DomainException;
final class ActorResolver {
    public static function current():Actor{$uid=(int)get_current_user_id();if($uid<1)throw new DomainException('Authentication required.','not_authenticated',401);$db=Db::wpdb();$emp=Db::table('employees');$rows=(array)$db->get_results($db->prepare("SELECT * FROM {$emp} WHERE wp_user_id=%d AND status='active' ORDER BY id",$uid),ARRAY_A);if(count($rows)===0)throw new DomainException('Active ERP employee identity required.','employee_identity_missing',403);if(count($rows)!==1)throw new DomainException('WordPress user is linked to multiple active ERP employee identities.','employee_identity_ambiguous',409);$e=$rows[0];$eid=(int)$e['id'];$company=(int)$e['company_id'];$caps=DesignationDefaults::forCode((string)$e['designation_code']);$roleCaps=(array)$db->get_col($db->prepare("SELECT DISTINCT rc.capability FROM ".Db::table('employee_roles')." er JOIN ".Db::table('role_capabilities')." rc ON rc.role_id=er.role_id JOIN ".Db::table('roles')." r ON r.id=er.role_id AND r.active=1 WHERE er.company_id=%d AND er.employee_id=%d AND er.active=1 AND rc.active=1",$company,$eid));$caps=array_merge($caps,$roleCaps);$ov=(array)$db->get_results($db->prepare("SELECT capability,effect FROM ".Db::table('employee_capability_overrides')." WHERE company_id=%d AND employee_id=%d AND active=1",$company,$eid),ARRAY_A);foreach($ov as$r){$cap=(string)$r['capability'];if($r['effect']==='grant')$caps[]=$cap;else$caps=array_values(array_diff($caps,[$cap]));}$caps=array_values(array_unique(array_map('strval',$caps)));$branchIds=BranchAuthority::ids($eid,$company);$designation=HierarchyScope::normaliseCode((string)$e['designation_code']);if(in_array($designation,['SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR','ZI','ZONAL_INSPECTOR','CM','CHAIRMAN','CHAIRMAN_MANAGING_DIRECTOR','MD','MANAGING_DIRECTOR'],true))$branchIds=array_map('intval',(array)$db->get_col($db->prepare("SELECT id FROM ".Db::table('branches')." WHERE company_id=%d AND status='active' ORDER BY is_head_office DESC,name",$company)));return new Actor($uid,$eid,$company,(int)$e['assigned_branch_id'],$branchIds,$caps,(string)$e['designation_code']);}
}
